import spacy, re

nlp = spacy.load("en_core_web_sm")

def extract_financial_entities(query_text: str) -> dict:
    """Extracts merchant, transaction amounts, and date ranges from search queries."""
    doc = nlp(query_text)
    entities = {"merchants": [], "amounts": [], "dates": []}
    for ent in doc.ents:
        if ent.label_ in ["ORG", "PERSON"]: entities["merchants"].append(ent.text)
        elif ent.label_ == "MONEY": entities["amounts"].append(ent.text)
        elif ent.label_ == "DATE": entities["dates"].append(ent.text)
    # Regex fallback for currency notation
    if not entities["amounts"]:
        entities["amounts"] = re.findall(r'\$\d+(?:\.\d{2})?', query_text)
    return entities
